window.getAtliProductById = function (id) {
  if (!id) return null;
  var normalized = String(id).trim().toUpperCase();
  return window.ATLI_PRODUCTS.find(function (p) {
    return p.id.toUpperCase() === normalized || p.sku.toUpperCase() === normalized;
  }) || null;
};

window.getAtliProductsByCategory = function (category) {
  if (!category || category === 'all') return window.ATLI_PRODUCTS.slice();
  return window.ATLI_PRODUCTS.filter(function (p) {
    return p.category === category;
  });
};

// Otomatik Katalog Kartı Oluşturucu (#productsGrid içerisine tüm 178 ürünü senkron olarak basar)
(function renderAllCatalogCards() {
  var grid = document.getElementById('productsGrid');
  if (!grid || !window.ATLI_PRODUCTS) return;
  var emptyState = document.getElementById('searchNoResults');

  var esc = function (s) {
    return String(s || '').replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  };

  var cardsHTML = window.ATLI_PRODUCTS.map(function (p) {
    var specsHTML = (p.specs || []).map(function (sp) {
      return '<li><i class="fas fa-check-circle" aria-hidden="true"></i> ' + esc(sp) + '</li>';
    }).join('');

    var waLink = 'https://wa.me/905363527416?text=' + encodeURIComponent('Merhaba, ' + p.title + ' (Kod: ' + p.sku + ') hakkında sipariş vermek ve bilgi almak istiyorum.');

    return (
      '<article class="product-card" data-category="' + esc(p.category) + '" data-id="' + esc(p.id) + '" data-sku="' + esc(p.sku) + '">' +
        '<div class="product-card__media">' +
          '<div class="product-card__brand-logo" title="' + esc(p.brand) + '">' +
            '<img src="' + esc(p.brandLogo) + '" alt="' + esc(p.brand) + '" class="brand-badge-img">' +
          '</div>' +
          '<img src="' + esc(p.image) + '" alt="' + esc(p.title) + '" class="product-card__img" loading="lazy" onerror="this.onerror=null;this.src=\'images/logo.png\';">' +
        '</div>' +
        '<div class="product-card__body">' +
          '<div class="product-card__meta-top">' +
            '<span class="product-card__cat">' + esc(p.categoryName) + '</span>' +
            '<span class="product-card__sku">Kod: ' + esc(p.sku) + '</span>' +
          '</div>' +
          '<h3 class="product-card__title">' + esc(p.title) + '</h3>' +
          '<p class="product-card__desc-text">' + esc(p.shortDescription || '') + '</p>' +
          '<ul class="product-card__specs">' + specsHTML + '</ul>' +
          '<div class="product-card__actions">' +
            '<a href="' + waLink + '" target="_blank" rel="noopener noreferrer" class="card-btn card-btn--primary btn-order-direct" data-order-direct data-id="' + esc(p.id) + '">' +
              '<i class="fab fa-whatsapp" aria-hidden="true"></i> Sipariş Ver' +
            '</a>' +
            '<button type="button" class="card-btn card-btn--outline btn-quick-view" data-quick-view data-id="' + esc(p.id) + '">' +
              '<i class="fas fa-eye" aria-hidden="true"></i> İncele' +
            '</button>' +
          '</div>' +
        '</div>' +
      '</article>'
    );
  }).join('');

  grid.innerHTML = cardsHTML;
  if (emptyState) {
    grid.appendChild(emptyState);
  }
})();
